"""Appendix A tables, computed from the task-level scores and the summaries of the scoring runs in data/scoring/ and the
paper's occupation measures file (data/pipeline/occ_measures.csv). Run from anywhere:
python3 code/tables/tabA-measurement.py. The Anthropic token counts (anthropic_usage.csv) and the subtask list (p0_subtasks.csv)
were summarized from the raw model output by code/prepare/scoring_summaries.py; the raw output is not distributed.
Writes output/tables/tabA-cost.tex, tabA-subtasks.tex, tabA-pilot.tex, tabA-agreement.tex, tabA-techfeas.tex,
tabA-weights.tex, tabA-adoption-reg.tex. Anthropic costs are token counts from the batch result files priced at
Claude Haiku 4.5 batch list prices (0.50 and 2.50 dollars per million input and output tokens; cache writes 0.625,
cache reads 0.05); OpenRouter costs are the runner's estimates from token counts at list prices (run logs)."""
import sys as _sys, pathlib as _pl; _sys.path.insert(0, str(_pl.Path(__file__).resolve().parents[1])); from paths import *   # repository-relative paths (code/paths.py)
import json, glob, os, re, numpy as np, pandas as pd
import statsmodels.api as sm
O = str(SCORING); T = str(TABLES)
HEAD = "% Generated by code/tables/tabA-measurement.py. Do not edit by hand.\n"
def table(caption, label, colspec, header, rows, notes, size="\\footnotesize"):
    L = [HEAD, "\\begin{table}[htbp]", "\\centering", "\\begin{threeparttable}", f"\\caption{{{caption}}}", f"\\label{{{label}}}", size, "\\begin{spacing}{1}",
         f"\\begin{{tabular}}{{{colspec}}}", "\\toprule", header + " \\\\", "\\midrule"] + rows + ["\\bottomrule", "\\end{tabular}", "\\end{spacing}", "\\begin{tablenotes}\\notesize", f"\\item Notes: {notes}", "\\end{tablenotes}", "\\end{threeparttable}", "\\end{table}", ""]
    return "\n".join(L)
def neg(x, f="{:.1f}"): s = f.format(x); return s.replace("-", "$-$") if s.startswith("-") else s
def W(name, text): open(os.path.join(T, name), "w").write(text); print("wrote", name)

# ---------- cost ----------
_AU = pd.read_csv(f"{O}/anthropic_usage.csv", dtype={"prompt": str}).set_index("prompt")   # token usage summed over the batch result files (code/prepare/scoring_summaries.py)
def anthropic(prompt):
    u = _AU.loc[prompt]
    cost = (u.input_tokens * 0.5 + u.output_tokens * 2.5 + u.cache_creation_input_tokens * 0.625 + u.cache_read_input_tokens * 0.05) / 1e6
    return int(u.requests), int(u.input_tokens + u.cache_read_input_tokens + u.cache_creation_input_tokens), int(u.output_tokens), cost
def orlog(d, p):
    j = json.load(open(f"{O}/runlogs/{d}/p{p}_full_runlog.json")); return j["prompt_tokens"], j["completion_tokens"], j["estimated_cost_usd"]
cost = {}
for p in "0abc": cost[("claude", p)] = anthropic(p)[3]
for d, m in (("gpt-luna-prod", "gpt"), ("gemini-flash-lite-prod", "gemini"), ("deepseek-v4-flash-prod", "deepseek")):
    for p in "abc": cost[(m, p)] = orlog(d, p)[2]
tok = {m: sum(orlog(d, p)[0] + orlog(d, p)[1] for p in "abc") for d, m in (("gpt-luna-prod", "gpt"), ("gemini-flash-lite-prod", "gemini"), ("deepseek-v4-flash-prod", "deepseek"))}
ctok = sum(anthropic(p)[1] + anthropic(p)[2] for p in "0abc")
mods = [("claude", "Claude Haiku 4.5"), ("gpt", "GPT-5.6-luna"), ("gemini", "Gemini 3.1 Flash-Lite"), ("deepseek", "DeepSeek V4 Flash")]
rows = []
for p, lab in (("0", "Prompt 0, subtask decomposition"), ("a", "Rating A, time savings"), ("b", "Rating B, independent completion"), ("c", "Rating C, human advantage")):
    rows.append(lab + " & " + " & ".join(f"{cost[(m, p)]:.1f}" if (m, p) in cost else "" for m, _ in mods) + " \\\\")
tot = {m: sum(v for (mm, p), v in cost.items() if mm == m) for m, _ in mods}
rows.append("\\midrule")
rows.append("Total & " + " & ".join(f"{tot[m]:.1f}" for m, _ in mods) + " \\\\")
rows.append("Tokens, millions & " + " & ".join(f"{(ctok if m == 'claude' else tok[m]) / 1e6:,.0f}" for m, _ in mods) + " \\\\")
three = tot["claude"] + tot["gpt"] + tot["gemini"]
# 8pt column gaps in the cost table so it fits the text width.
W("tabA-cost.tex", table("API cost of the scoring runs, by model and prompt (US dollars)", "tab:cost", "@{}l@{\\hspace{8pt}}r@{\\hspace{8pt}}r@{\\hspace{8pt}}r@{\\hspace{8pt}}r@{}", " & " + " & ".join(l for _, l in mods), rows,
  f"Each cell is the cost of running the prompt on all 19,281 tasks at all four stages. Claude Haiku 4.5 ran through the Anthropic Message Batches API on April 10, 2026, and its costs are token counts from the batch results priced at the batch list prices (0.50 and 2.50 dollars per million input and output tokens, 0.05 for cached input). The other three models ran through OpenRouter on August 1 and 2, 2026, and their costs are the runner's estimates from token counts at list prices. Prompt 0 was run once, by Claude, and its subtasks were used for every model. The three-model score (Claude, GPT, and Gemini) cost {three:,.0f} dollars; DeepSeek V4 Flash is the fourth model of Appendix~\\ref{{app:reliability}} and is not part of the score. The totals exclude the pilot of Appendix Table~\\ref{{tab:pilot}}, the retests, and the whole-task check of Appendix~\\ref{{app:subtasks}}; the OpenRouter account as a whole recorded 652 dollars, 265 thousand requests, and 1.41 billion tokens over the project."))
print("three-model cost", round(three, 1), {m: round(v, 1) for m, v in tot.items()})

# ---------- subtasks ----------
p0 = pd.read_parquet(f"{O}/parquet/production/prompt_0_summary.parquet"); dist = p0.num_subtasks.value_counts().sort_index()
act = {}; shares = []
for s in pd.read_csv(f"{O}/p0_subtasks.csv").itertuples():   # every subtask of the Prompt 0 decomposition
    act[s.activity_type] = act.get(s.activity_type, 0) + s.pct_of_total_time; shares.append(s.pct_of_total_time)
AT = {"information_gathering": "Gathering information", "information_processing": "Processing information", "content_generation": "Generating content", "communication_coordination": "Communication and coordination", "decision_judgment": "Decision and judgment", "physical_execution": "Physical execution", "administrative_procedural": "Administrative and procedural work"}
tota = sum(act.values()); rows = ["\\multicolumn{2}{@{}l}{\\emph{A. Subtasks per task}} \\\\"]
for k, v in dist.items(): rows.append(f"{k} subtasks & {v:,} tasks ({100 * v / len(p0):.1f} percent) \\\\")
rows.append(f"Total & {int(p0.num_subtasks.sum()):,} subtasks in {len(p0):,} tasks, {p0.num_subtasks.mean():.2f} per task \\\\")
sh = np.array(shares); rows.append(f"Time share of a subtask & median {np.median(sh):.0f} percent, 10th to 90th percentile {np.percentile(sh, 10):.0f} to {np.percentile(sh, 90):.0f} \\\\")
rows += ["\\addlinespace", "\\multicolumn{2}{@{}l}{\\emph{B. Share of task time by activity type (percent)}} \\\\"]
for k, v in sorted(act.items(), key=lambda x: -x[1]): rows.append(f"{AT[k]} & {100 * v / tota:.1f} \\\\")
W("tabA-subtasks.tex", table("The subtask decomposition: counts, time shares, and activity types", "tab:subtasks", "@{}ll@{}", " & ", rows,
  "Prompt 0 (Appendix~\\ref{app:prompts}) split each of the 19,281 O*NET task statements into three to seven subtasks with integer time shares summing to 100 and one of seven activity types; no task received seven. Panel B weights each subtask by its time share.", "\\footnotesize"))
print("subtasks", int(p0.num_subtasks.sum()), dist.to_dict())

# ---------- pilot ----------
def pcost(d): return sum(json.load(open(f))["estimated_cost_usd"] for f in glob.glob(f"{O}/runlogs/{d}/p[abc]_pilot1000_runlog.json"))
pil = [("Gemini 3.1 Flash-Lite", "Google", "0.898", "0.973", "100 / 100 / 100", pcost("gemini-flash-lite"), "selected"),
       ("GPT-5.6-luna", "OpenAI", "0.866", "0.899", "100 / 99.6 / 100", pcost("gpt-luna"), "selected"),
       ("GPT-5 mini", "OpenAI", "0.798", "0.860", "100 / 100 / 100", pcost("gpt-5-mini"), "not selected"),
       ("DeepSeek V4 Flash", "DeepSeek", "0.830", "0.845", "100 / 100 / 100", pcost("deepseek-v4-flash"), "selected as the fourth model"),
       ("DeepSeek V4 Pro", "DeepSeek", "0.812", "0.811", "100 / 100 / 100", pcost("deepseek-v4-pro"), "not selected"),
       ("Kimi K2.5", "Moonshot", "", "", "stopped after A and B", pcost("kimi-k2.5"), "not selected"),
       ("Kimi K2.6", "Moonshot", "", "", "stopped after A", pcost("kimi-k2.6"), "not selected")]
rows = [f"{m} & {lab} & {ag} & {rt} & {cov} & {c:.1f} & {dec} \\\\" for m, lab, ag, rt, cov, c, dec in pil]
rows += ["\\midrule", "Claude Haiku 4.5, second run & Anthropic & 0.975 & & 100 / 100 / 100 & about 10 & the original model \\\\"]
W("tabA-pilot.tex", table("The pilot: seven candidate models on 1,000 tasks, August 1, 2026", "tab:pilot", "@{}llccccl@{}", "Model & Developer & \\shortstack{Agreement\\\\with Claude} & \\shortstack{Retest,\\\\rating A} & \\shortstack{Coverage,\\\\A / B / C (percent)} & \\shortstack{Cost\\\\(dollars)} & Decision", rows,
  "The 1,000 tasks are a stratified sample of the 19,281, with every major occupation group represented. Every model rated the same fixed subtasks with ratings A, B, and C at all four stages through OpenRouter, with temperature 0, seed 12345, and JSON output. Agreement is the Spearman correlation across tasks between the model's stage-4 composite score and Claude Haiku 4.5's original score; retest is the Spearman correlation between two runs of rating A, stage 4. Cost covers ratings A, B, and C on the 1,000 tasks. The two Kimi models were stopped because their long reasoning output made them slow (about 400 requests an hour); Gemini 3.5 Flash was dropped before the pilot on its projected cost. Within each developer the cheaper model agreed with Claude at least as well as the dearer one. The last row re-ran the original Claude pipeline on the same 1,000 tasks through the Anthropic batch API; its agreement column is the correlation between the two Claude runs.", "\\scriptsize"))

# ---------- agreement across models and runs ----------
m = pd.read_csv(f"{O}/master_task_scores.csv")
M = [("claude", "Claude"), ("gemini_flash_lite", "Gemini"), ("gpt_luna", "GPT"), ("deepseek_v4_flash", "DeepSeek")]
c4 = m[[f"{k}_composite_s4" for k, _ in M]].dropna(); sp = c4.corr("spearman")
rows = ["\\multicolumn{5}{@{}l}{\\emph{A. Task level: Spearman correlations of the stage-4 score across models (" + f"{len(c4):,}" + " tasks)}} \\\\", " & " + " & ".join(l for _, l in M) + " \\\\"]
for i, (k, l) in enumerate(M): rows.append(l + " & " + " & ".join(f"{sp.iloc[i, j]:.3f}" if j < i else ("1" if i == j else "") for j in range(4)) + " \\\\")
rows.append("Mean stage-4 score & " + " & ".join(f"{c4[f'{k}_composite_s4'].mean():.1f}" for k, _ in M) + " \\\\")
rows += ["\\addlinespace", "\\multicolumn{5}{@{}l}{\\emph{B. Task level: Claude Haiku 4.5 rated twice, Spearman correlation between runs on 1,000 tasks}} \\\\", " & Stage 1 & Stage 2 & Stage 3 & Stage 4 \\\\"]
for p, lab, pat in (("a", "Rating A, feasible time savings", "stage_{}_feasible"), ("b", "Rating B, feasible completion", "stage_{}_feasible"), ("c", "Rating C, human advantage", "stage_{}_human_advantage")):
    r = pd.read_parquet(f"{O}/parquet/claude-rerun/prompt_{p}_summary.parquet"); o = pd.read_parquet(f"{O}/parquet/production/prompt_{p}_summary.parquet"); mg = r.merge(o, on="task_id", suffixes=("_r", "_o"))
    rows.append(lab + " & " + " & ".join(f"{mg[[pat.format(s) + '_r', pat.format(s) + '_o']].dropna().corr('spearman').iloc[0, 1]:.3f}" for s in range(1, 5)) + " \\\\")
oc = {k: pd.read_csv(f"{O}/occupation_scores_all_weights_{k}.csv").set_index("onet_code") for k in ("gemini_flash_lite", "gpt_luna", "deepseek_v4_flash", "ensemble3", "ensemble4")}
e3 = oc["ensemble3"]; rows += ["\\addlinespace", "\\multicolumn{5}{@{}l}{\\emph{C. Occupation level: Spearman correlation with the three-model score (" + f"{len(e3):,}" + " occupations)}} \\\\", " & Gemini & GPT & DeepSeek & Four-model score \\\\"]
def occ_corr(col):
    out = []
    for k in ("gemini_flash_lite", "gpt_luna", "deepseek_v4_flash", "ensemble4"):
        d = pd.concat([e3[col], oc[k][col]], axis=1).dropna(); out.append(f"{d.corr('spearman').iloc[0, 1]:.3f}")
    return out
rows.append("Stage-4 score & " + " & ".join(occ_corr("stage_4_composite_relevance_wt")) + " \\\\")
for k in oc: oc[k]["d41"] = oc[k]["stage_4_composite_relevance_wt"] - oc[k]["stage_1_composite_relevance_wt"]
rows.append("Change from stage 1 to stage 4 & " + " & ".join(occ_corr("d41")) + " \\\\")
W("tabA-agreement.tex", table("Agreement across models and across runs", "tab:agreement", "@{}lcccc@{}", "", rows,
  "Panel A uses the production runs on all tasks; each model's score is the composite of its own three ratings. Panel B compares the original April 2026 Claude run with a second run of the same pipeline in August 2026 on the stratified 1,000-task pilot sample. Panel C aggregates each model's task scores to occupations with the relevance weights of Section~\\ref{sec:construction} and correlates them with the three-model score of the paper; the four-model score adds DeepSeek V4 Flash. The Claude column of Panel C is omitted because Claude's occupation scores enter the three-model score.", "\\footnotesize"))
print("task-level spearman matrix\n", sp.round(3))

# ---------- technical vs feasible ----------
CM = ["claude", "gpt_luna", "gemini_flash_lite"]
for s in range(1, 5):
    for kind in ("technical", "feasible"):
        m[f"e3_{kind}_s{s}"] = pd.concat([(m[f"{md}_a_s{s}_{kind}"] + m[f"{md}_b_s{s}_{kind}"] + (100 - m[f"{md}_c_s{s}_human_advantage"])) / 3 for md in CM], axis=1).mean(axis=1, skipna=False)
rows = ["\\multicolumn{5}{@{}l}{\\emph{A. Three-model score, by stage}} \\\\", " & Capability only & Constraint adjusted & Pearson & Spearman \\\\"]
for s in range(1, 5):
    d = m[[f"e3_technical_s{s}", f"e3_feasible_s{s}"]].dropna(); rows.append(f"Stage {s} & {d.iloc[:, 0].mean():.1f} & {d.iloc[:, 1].mean():.1f} & {d.corr().iloc[0, 1]:.3f} & {d.corr('spearman').iloc[0, 1]:.3f} \\\\")
d = m[["e3_technical_s4", "e3_technical_s1", "e3_feasible_s4", "e3_feasible_s1"]].dropna(); dt = d.e3_technical_s4 - d.e3_technical_s1; df_ = d.e3_feasible_s4 - d.e3_feasible_s1
rows.append(f"Change, stage 1 to 4 & {dt.mean():.1f} & {df_.mean():.1f} & {np.corrcoef(dt, df_)[0, 1]:.3f} & {pd.concat([dt, df_], axis=1).corr('spearman').iloc[0, 1]:.3f} \\\\")
rows += ["\\addlinespace", "\\multicolumn{5}{@{}l}{\\emph{B. Each model, stage 4}} \\\\"]
for md, lab in (("claude", "Claude Haiku 4.5"), ("gpt_luna", "GPT-5.6-luna"), ("gemini_flash_lite", "Gemini 3.1 Flash-Lite")):
    t = (m[f"{md}_a_s4_technical"] + m[f"{md}_b_s4_technical"] + (100 - m[f"{md}_c_s4_human_advantage"])) / 3; f = (m[f"{md}_a_s4_feasible"] + m[f"{md}_b_s4_feasible"] + (100 - m[f"{md}_c_s4_human_advantage"])) / 3; d = pd.concat([t, f], axis=1).dropna()
    rows.append(f"{lab} & {d.iloc[:, 0].mean():.1f} & {d.iloc[:, 1].mean():.1f} & {d.corr().iloc[0, 1]:.3f} & {d.corr('spearman').iloc[0, 1]:.3f} \\\\")
W("tabA-techfeas.tex", table("Capability-only and constraint-adjusted scores across tasks", "tab:techfeas", "@{}lcccc@{}", "", rows,
  f"Ratings A and B were each given in two versions: the capability of the technology alone, and the rating after the economic, regulatory, and organizational constraints on using AI for the subtask, which the paper uses. Rating C has one version and enters both composites. Means are across the {len(m[['e3_technical_s4', 'e3_feasible_s4']].dropna()):,} tasks with all three models; correlations are across tasks. The change rows compare each version's change from stage 1 to stage 4.", "\\footnotesize"))

# ---------- weights ----------
rows = [" & Pearson & Spearman & Pearson & Spearman \\\\"]
for w, lab in (("simple_avg", "Simple average"), ("importance_wt", "Importance weights"), ("frequency_wt", "Frequency weights")):
    d4 = e3[["stage_4_composite_relevance_wt", f"stage_4_composite_{w}"]].dropna(); dd = pd.concat([e3["d41"], e3[f"stage_4_composite_{w}"] - e3[f"stage_1_composite_{w}"]], axis=1).dropna()
    rows.append(f"{lab} & {d4.corr().iloc[0, 1]:.3f} & {d4.corr('spearman').iloc[0, 1]:.3f} & {dd.corr().iloc[0, 1]:.3f} & {dd.corr('spearman').iloc[0, 1]:.3f} \\\\")
X = e3[["stage_4_prompt_a_feasible_relevance_wt", "stage_4_prompt_b_feasible_relevance_wt", "stage_4_prompt_c_human_advantage_relevance_wt"]].dropna().copy(); X.iloc[:, 2] = 100 - X.iloc[:, 2]
Z = (X - X.mean()) / X.std(); U, S, Vt = np.linalg.svd(Z.values, full_matrices=False); ve = S ** 2 / np.sum(S ** 2); pc1 = Z.values @ Vt[0]; r1 = abs(np.corrcoef(pc1, X.mean(axis=1))[0, 1])
W("tabA-weights.tex", table("Occupation scores under alternative task weights", "tab:weights", "@{}lcccc@{}", " & \\multicolumn{2}{c}{Stage-4 score} & \\multicolumn{2}{c}{Change, stage 1 to 4}", rows,
  f"Three-model score across the {len(e3):,} O*NET occupations. The paper weights an occupation's tasks by O*NET relevance, the share of incumbents who report the task as part of their job; the alternatives weight tasks equally, by O*NET importance, or by O*NET frequency. Each cell is the correlation across occupations between the alternative score and the relevance-weighted score. A principal-components analysis of the three relevance-weighted ratings (A, B, and 100 minus C) at stage 4 across occupations gives a first component that accounts for " + f"{100 * ve[0]:.1f}" + " percent of their variance with loadings of " + f"{abs(Vt[0][0]):.2f}, {abs(Vt[0][1]):.2f}, and {abs(Vt[0][2]):.2f}" + ", and that correlates " + f"{r1:.4f}" + " with the equal-weight score.", "\\footnotesize"))
print("weights/PCA", round(100 * ve[0], 1), round(r1, 4))

# ---------- adoption regressions ----------
om = pd.read_csv(PIPELINE / "occ_measures.csv"); d = om.dropna(subset=["rps_adoption", "rps_n", "d_ens_s4_s1", "d_ens_s3_s1", "ensemble3_s1", "ensemble3_s4"]); d = d[d.rps_n >= 20].copy()
cx = om.dropna(subset=["d_ens_s4_s1", "dv_rating_gamma", "felten_aioe"]); r_el = cx[["d_ens_s4_s1", "dv_rating_gamma"]].corr().iloc[0, 1]; r_fe = cx[["d_ens_s4_s1", "felten_aioe"]].corr().iloc[0, 1]; r_s1 = cx[["ensemble3_s1", "dv_rating_gamma"]].corr().iloc[0, 1]
def z(x, w): mu = np.average(x, weights=w); sd = np.sqrt(np.average((x - mu) ** 2, weights=w)); return (x - mu) / sd
specs = [(["d_ens_s4_s1"],), (["ensemble3_s4"],), (["ensemble3_s4", "ensemble3_s1"],), (["dv_rating_gamma"],), (["d_ens_s4_s1", "dv_rating_gamma"],), (["d_ens_s3_s1", "dv_rating_gamma"],), (["felten_aioe"],), (["d_ens_s4_s1", "felten_aioe"],)]
NAMES = {"d_ens_s4_s1": "Our change, stage 1 to 4", "d_ens_s3_s1": "Our change, stage 1 to 3", "ensemble3_s4": "Our stage-4 level", "ensemble3_s1": "Our stage-1 level", "dv_rating_gamma": "Eloundou et al.\\ (2024), $\\zeta$", "felten_aioe": "Felten et al.\\ (2023)"}
res = []
for (cols,) in specs:
    dd = d.dropna(subset=cols); X = sm.add_constant(pd.DataFrame({c: z(dd[c], dd.rps_n) for c in cols})); y = 100 * dd.rps_adoption
    res.append((cols, sm.WLS(y, X, weights=dd.rps_n).fit(cov_type="HC1"), len(dd)))
order = ["d_ens_s4_s1", "d_ens_s3_s1", "ensemble3_s4", "ensemble3_s1", "dv_rating_gamma", "felten_aioe"]
rows = [" & " + " & ".join(f"({i + 1})" for i in range(len(res))) + " \\\\", "\\midrule"]
for v in order:
    rows.append(NAMES[v] + " & " + " & ".join(neg(r.params[v], "{:.2f}") if v in cols else "" for cols, r, n in res) + " \\\\")
    rows.append(" & " + " & ".join(f"({r.bse[v]:.2f})" if v in cols else "" for cols, r, n in res) + " \\\\")
rows += ["\\midrule", "$R^{2}$ & " + " & ".join(f"{r.rsquared:.2f}" for cols, r, n in res) + " \\\\", "Occupations & " + " & ".join(f"{n}" for cols, r, n in res) + " \\\\"]
W("tabA-adoption-reg.tex", table("Reported adoption regressed on exposure measures", "tab:adoptionreg", "@{}l*{8}{c}@{}", "", rows,
  "The dependent variable is the share of workers in the occupation who report using generative AI at work, in percentage points, from four waves of the Real-Time Population Survey of \\citet{bick2026work}, August 2025 to May 2026, for the occupations with at least 20 respondents. Each regressor is standardized to mean zero and standard deviation one, weighted by respondents, so a coefficient is the change in adoption, in percentage points, per standard deviation of the measure. Regressions are weighted by respondents, with heteroskedasticity-robust standard errors in parentheses. Columns (5) and (6) add the Eloundou et al.\\ measure to our change, and column (8) adds the Felten et al.\\ measure. Across the " + f"{len(cx)}" + " census occupations with all measures, our change from stage 1 to stage 4 correlates " + f"{r_el:.2f}" + " with the Eloundou et al.\\ measure and " + f"{r_fe:.2f}" + " with the Felten et al.\\ measure, and our stage-1 level correlates " + f"{r_s1:.2f}" + " with the Eloundou et al.\\ measure.", "\\footnotesize"))
for cols, r, n in res: print(cols, {c: (round(r.params[c], 2), round(r.bse[c], 2)) for c in cols}, round(r.rsquared, 2))
